@location('Sources/WIMLib/WIMFile.swift')
imagine final class WIMFile {
    public init(path: String) throws                          // wimlib_open_wim, flags 0
    public var images: [WIMImage] { get }                       // 1-based index 순서
    public func extract(paths: [String], fromImage index: Int, to directory: URL) throws     // P6
    public func close()                                         // wimlib_free. 두 번 불러도 안전. deinit에서도 부른다.
    public static func create(from directory: URL, to path: String, compression: WIMCompression = .lzx,
                              imageName: String, properties: [String: String] = [:]) throws   // P8
    public static var wimlibVersion: String { get }             // wimlib_get_version_string

    requirements(`
        열기 실패, 없는 이미지 인덱스, 없는 경로는 WIMLibError로 던진다. wimlib 에러 코드와 메시지를 담는다.
        extract는 대상 디렉터리가 없으면 WIMLibError.posix(ENOENT)로 던진다 (wimlib이 만들지 않는다).
    `);
    ensure(`create로 만든 WIM(LZX, 파일 3개: 빈 파일, 100 B, 1 MiB + 17 B 무작위)을 열면 images.count == 1, images[0].name == imageName`);
    ensure(`properties: ["WINDOWS/ARCH": "9", "WINDOWS/VERSION/BUILD": "26200"]로 만들면 images[0].architecture == .x64, build == 26200`);
    ensure(`extract(paths: ["/dir/a.bin"], fromImage: 1, to: tmp) 뒤 tmp/a.bin의 바이트가 원본과 같다 (NO_PRESERVE_DIR_STRUCTURE라 dir/ 없이 놓인다)`);
    ensure(`extract(paths: ["/dir"], ...)는 dir 안의 파일들을 tmp에 평평하게 놓는다`);
    ensure(`없는 경로 → WIMLibError.wimlib(code: WIMLIB_ERR_PATH_DOES_NOT_EXIST, …)`);
    ensure(`fromImage: 2 (이미지가 하나뿐) → WIMLibError.wimlib(code: WIMLIB_ERR_INVALID_IMAGE, …)`);
    ensure(`빈 파일을 열면 throws`);
    ensure(`close() 두 번 → 두 번째는 아무 일도 하지 않는다. close() 뒤 images → WIMLibError.closed`);
    ensure(`같은 프로세스에서 create → open → extract를 20번 반복해도 성공한다 (전역 상태 누수 검사)`);
}

@location('Sources/WIMLib/WIMImage.swift')
public struct WIMImage: Sendable {
    public let index: Int                                       // 1부터
    public let name: String?
    public let description: String?
    public let displayName: String?                             // DISPLAYNAME
    public let architecture: WIMArchitecture?                   // WINDOWS/ARCH: 0 x86, 5 arm, 9 x64, 12 arm64. 그 밖은 .other(Int)
    public let major: Int?, minor: Int?, build: Int?            // WINDOWS/VERSION/*
    public func property(_ name: String) -> String?             // 임의 XML 경로. P7
}
public enum WIMArchitecture: Sendable, Equatable { case x86, arm, x64, arm64, other(Int) }
public enum WIMCompression: Sendable { case none, xpress, lzx }

@location('Sources/WIMLib/WIMLibError.swift')
public enum WIMLibError: Error {
    case wimlib(code: Int32, message: String)
    case posix(operation: String, path: String?, errno: Int32)
    case closed
}
